Percent = fun(perc, pixels) {
result = Math.Int(Math.Abs(Math.Int(pixels)) / 100 * Math.Abs(Math.Int(perc)));
return result;
};
Limit = fun(width, height, perc) {
local.this;
this.width = width;
this.height = height;
this.perc = perc;
this.GetWidth = fun() {
width = Percent(this.perc, this.width);
return width;
};
this.GetHeight = fun() {
height = Percent(this.perc, this.height);
return height;
};
return this;
};
